In this updated script, the `IsCodeCorrect` method is called inside the `OnFieldValueChanged` method. This ensures that the input fields are checked for correctness immediately after any change.

To achieve this, you need to dynamically create input fields at the positions where spaces are in the sentence. You can then check if the input fields contain the correct words when the user finishes entering the text.

Here's a script that does this:

1. Create a prefab with an `InputField` component.
2. Use the script below to dynamically create input fields and check the correctness of the input.

```c#
using System;
using System.Collections.Generic;
using Screens.Bases;
using TMPro;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using ColorUtility = UnityEngine.ColorUtility;

namespace Screens
{
    public class Screen8StringCheck : ScreenBase
    {
        [SerializeField] private GameObject inputFieldPrefab;
        [SerializeField] private Transform inputFieldParent;
        [SerializeField] private string sentence;
        [SerializeField] private GameObject failedGO;

        private List<InputField> inputFields = new List<InputField>();
        private string[] correctWords;

        protected override void Start()
        {
            Init();
        }

        private void Init()
        {
            base.Start();
            correctWords = sentence.Split(' ');

            for (int i = 0; i < correctWords.Length; i++)
            {
                if (string.IsNullOrEmpty(correctWords[i]))
                {
                    continue;
                }

                GameObject inputFieldGO = Instantiate(inputFieldPrefab, inputFieldParent);
                InputField inputField = inputFieldGO.GetComponent<InputField>();
                inputField.characterLimit = correctWords[i].Length;
                int i1 = i;
                inputField.onValueChanged.AddListener(delegate(string text) { OnFieldValueChanged(i1, text); });
                inputField.onEndEdit.AddListener(delegate(string text) { OnFieldValueChanged(i1, text); });
                inputFields.Add(inputField);
            }
        }

        private void OnFieldValueChanged(int i, string text)
        {
            IsCodeCorrect();
        }

        private void IsCodeCorrect()
        {
            // Check if all fields are filled
            foreach (InputField inputField in inputFields)
            {
                if (inputField.text == "")
                {
                    DeactivateFailedMessage();
                    return;
                }
            }

            bool isCodeCorrect = true;
            for (int i = 0; i < inputFields.Count; i++)
            {
                if (inputFields[i].text != correctWords[i])
                {
                    isCodeCorrect = false;
                }
            }

            if (isCodeCorrect)
            {
                DeactivateFailedMessage();
                EventManager.AssignmentCompleted.Invoke();
            }
            else
            {
                ActivateFailedMessage();
            }
        }

        private void DeactivateFailedMessage()
        {
            failedGO.SetActive(false);
            // Change color of input fields
            foreach (InputField inputField in inputFields)
            {
                inputField.image.color = Color.white;
            }
        }

        private void ActivateFailedMessage()
        {
            failedGO.SetActive(true);
            foreach (InputField inputField in inputFields)
            {
                bool parseSuccess = ColorUtility.TryParseHtmlString("#FF4050", out Color newCol);
                inputField.image.color = newCol;
            }
        }
    }
}
```

### Steps to Use the Script

1. **Create an InputField Prefab:**
   - Create a new `GameObject` in your scene.
   - Add an `InputField` component to it.
   - Customize the `InputField` as needed (e.g., set the font, size, etc.).
   - Save this `GameObject` as a prefab (e.g., `InputFieldPrefab`).

2. **Set Up the Scene:**
   - Create an empty `GameObject` in your scene to act as the parent for the input fields (e.g., `InputFieldParent`).
   - Add the `Screen8StringCheck` script to a `GameObject` in your scene.
   - Assign the `InputFieldPrefab` and `InputFieldParent` to the corresponding fields in the `Screen8StringCheck` script.
   - Set the `sentence` field to the sentence you want to use.

3. **Run the Scene:**
   - When you run the scene, the script will dynamically create input fields at the positions where spaces are in the sentence.
   - The script will check if the input fields contain the correct words when the user finishes entering the text.

This approach allows you to dynamically create input fields based on the sentence and check if the user has entered the correct words.

