        [SerializeField] private GameObject failedGO;

        private List<TMP_InputField> inputFields = new List<TMP_InputField>();
        private List<string> correctWords = new List<string>();

        protected override void Start()
        {
            Init();
        }

        private void Init()
        {
            base.Start();

